/* Experimental reference geometry around original Swiss/SOFA primitives.
 * No ephemeris coordinates are taken from Swiss here. Hindu beta=0 retains
 * the controlled native source plane, after independent JPL apparent optics.
 */
#include <math.h>
#include "sofa.h"
#include "swephexp.h"
#include "swephlib.h"

static int original_native_frame(double tt,double result[3][3]) {
    double pb[3][3],nut[3][3],angles[6];int i,j;char error[256]={0};
    if(swe_calc(tt,SE_ECL_NUT,SEFLG_MOSEPH,angles,error)<0)return -1;
    for(j=0;j<3;++j) {
        double v[6]={0,0,0,0,0,0};v[j]=1;
        swi_bias(v,tt,SEFLG_MOSEPH,0);swi_precess(v,tt,SEFLG_MOSEPH,-1);
        for(i=0;i<3;++i)pb[i][j]=v[i];
    }
    iauNumat(angles[1]*M_PI/180,angles[2]*M_PI/180,angles[3]*M_PI/180,nut);
    iauRxr(nut,pb,result);return 0;
}

int fb_reference_receiver(double tt, double ut1, double lon, double lat, double height,
                      double *out) {
    double n[3][3],c2i[3][3],pv[2][3],position[3],velocity[3],theta,gast;int i,j;
    if(tt>=2378495.0 && tt<=2524595.0) {
        iauPnm06a(tt,0,n);iauC2i06a(tt,0,c2i);theta=iauEra00(ut1,0);
        iauPvtob(lon*M_PI/180,lat*M_PI/180,height,0,0,0,theta,pv);
        iauTrxp(c2i,pv[0],position);iauTrxp(c2i,pv[1],velocity);
        gast=iauGst06(ut1,0,tt,0,n);
    } else {
        double edge=tt<2451545?2378495.0:2524595.0;
        double edge_ut=edge,b[3][3],b_t[3][3],modern[3][3],current[3][3],temp[3][3];
        char error[256]={0};
        for(i=0;i<5;++i)edge_ut=edge-swe_deltat_ex(edge_ut,edge_ut<2436934.5?-1:2,error);
        if(original_native_frame(tt,current)<0 || original_native_frame(edge,b)<0)return -1;
        iauTr(b,b_t);iauPnm06a(edge,0,modern);iauRxr(current,b_t,temp);iauRxr(temp,modern,n);
        gast=(swe_sidtime(ut1)*15+iauGst06(edge_ut,0,edge,0,modern)*180/M_PI-swe_sidtime(edge_ut)*15)*M_PI/180;
        iauPvtob(lon*M_PI/180,lat*M_PI/180,height,0,0,0,gast,pv);
        iauTrxp(n,pv[0],position);iauTrxp(n,pv[1],velocity);
    }
    for(i=0;i<34;++i)out[i]=0;
    for(i=0;i<3;++i) {
        out[i]=position[i]/149597870700.;out[3+i]=velocity[i]*86400/149597870700.;
        for(j=0;j<3;++j)out[21+3*i+j]=n[i][j];
    }
    out[30]=iauAnp(gast)*180/M_PI;
    return 0;
}

int fb_reduce_reference_direction(double tt, double lon, double lat, int definition,
                              const double *observer, const double *apparent,
                              double *out) {
    double frame[3][3],pb[3][3],nut[3][3],p[3][3],angles[6],equ[3],icrs[3],target[3];
    double lambda,epsilon,local,phi,east,north,up; int i,j; char error[256]={0};
    for(i=0;i<3;++i) for(j=0;j<3;++j) frame[i][j]=observer[21+3*i+j];
    if(definition==0) {
        if(swe_calc(tt,SE_ECL_NUT,SEFLG_MOSEPH,angles,error)<0) return -1;
        for(j=0;j<3;++j) {
            double v[6]={0,0,0,0,0,0};v[j]=1;
            swi_bias(v,tt,SEFLG_MOSEPH,0);swi_precess(v,tt,SEFLG_MOSEPH,-1);
            for(i=0;i<3;++i)pb[i][j]=v[i];
        }
        iauNumat(angles[1]*M_PI/180,angles[2]*M_PI/180,angles[3]*M_PI/180,nut);
        iauRxr(nut,pb,p);iauRxp(p,(double *)apparent,equ);
        epsilon=angles[0]*M_PI/180;
        lambda=atan2(equ[1]*cos(epsilon)+equ[2]*sin(epsilon),equ[0]);
        equ[0]=cos(lambda);equ[1]=sin(lambda)*cos(epsilon);equ[2]=sin(lambda)*sin(epsilon);
        iauTrxp(p,equ,icrs);iauRxp(frame,icrs,target);
    } else {
        iauRxp(frame,(double *)apparent,target);
    }
    local=(observer[30]+lon)*M_PI/180;phi=lat*M_PI/180;
    east=-sin(local)*target[0]+cos(local)*target[1];
    north=-sin(phi)*cos(local)*target[0]-sin(phi)*sin(local)*target[1]+cos(phi)*target[2];
    up=cos(phi)*cos(local)*target[0]+cos(phi)*sin(local)*target[1]+sin(phi)*target[2];
    for(i=0;i<3;++i)out[i]=target[i];
    out[3]=atan2(up,hypot(east,north))*180/M_PI;
    return 0;
}
